{
  "title": "The Gilded Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined city gates.",
      "visual_description": "Cracked stone gates loom under a grey sky, rusted portcullis half-lifted, old royal banners tattered above the arch.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings at the outer market.",
      "visual_description": "Ragged townspeople huddle near collapsed stalls, pointing nervously toward the inner city as patrols march in the distance.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker", "Frightened Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "Kael scouts ahead to the first cursed tower.",
      "visual_description": "A twisted stone tower with glowing runes, a single dark window flickering with purple light, shadowy vines crawling up the walls.",
      "characters": ["Kael the Scout", "Lira the Map Reader"]
    },
    {
      "scene_number": 4,
      "caption": "The party debates entering the tower for a rumored key.",
      "visual_description": "Lira spreads a worn map on a broken pillar, pointing at the tower while Finn nervously checks his pack and Zara gazes upward.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker"]
    },
    {
      "scene_number": 5,
      "caption": "Inside the tower, an illusion of treasure tempts them.",
      "visual_description": "A circular room with a floating golden chest, coins spilling out, but the floor is covered in faint magical sigils that pulse.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker"]
    },
    {
      "scene_number": 6,
      "caption": "Mira dispels the illusion, revealing a hidden passage.",
      "visual_description": "Mira raises her hands, golden light bursts from her palms, the treasure fades into a dark stairwell leading downward.",
      "characters": ["Mira the Magic Helper", "Finn the Comic Relief Official"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march through the main courtyard.",
      "visual_description": "A line of soldiers in dented plate armor, carrying spears and torches, march under the shadow of the castle keep.",
      "characters": ["Armored Patrols", "Kael the Scout"]
    },
    {
      "scene_number": 8,
      "caption": "Kael leads the party through a forgotten garden.",
      "visual_description": "Overgrown hedges and statues of kings, moss-covered fountains, a rusted iron gate half-hidden behind ivy.",
      "characters": ["Kael the Scout", "Lira the Map Reader", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker"]
    },
    {
      "scene_number": 9,
      "caption": "They encounter a magic door that speaks in riddles.",
      "visual_description": "A tall door of black wood with a silver face carved into it, eyes glowing blue, runes shifting on its surface.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker", "The Magic Door"]
    },
    {
      "scene_number": 10,
      "caption": "Finn solves the riddle by accident, opening the door.",
      "visual_description": "Finn stumbles and blurts a nonsense answer, the door's eyes widen, then it swings open with a groan, revealing a torchlit corridor.",
      "characters": ["Finn the Comic Relief Official", "The Magic Door"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the castle keep, they find the captive held in a throne room.",
      "visual_description": "A grand hall with shattered stained glass, a dark throne on a dais, and a shimmering cage hanging from chains near the ceiling.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker", "The Captive"]
    },
    {
      "scene_number": 12,
      "caption": "Zara uses her rope and agility to reach the cage.",
      "visual_description": "Zara swings across the hall on a chandelier chain, grabbing the cage bars as guards burst through a side door.",
      "characters": ["Zara the Bridge Walker", "The Captive", "Armored Patrols"]
    },
    {
      "scene_number": 13,
      "caption": "Mira holds off the guards with a blinding light spell.",
      "visual_description": "Mira stands at the entrance, hands out, a brilliant white flash erupts, forcing the armored patrols to shield their eyes.",
      "characters": ["Mira the Magic Helper", "Armored Patrols"]
    },
    {
      "scene_number": 14,
      "caption": "Kael picks the cage lock as Lira watches the hall.",
      "visual_description": "Kael works a thin tool into the cage's lock, Lira stands watch with a drawn bow, arrows nocked.",
      "characters": ["Kael the Scout", "Lira the Map Reader", "The Captive"]
    },
    {
      "scene_number": 15,
      "caption": "The freed captive reveals the dragon rumor is true.",
      "visual_description": "The captive, a young woman in torn robes, points to a high window where a shadow passes, a distant roar shakes the walls.",
      "characters": ["The Captive", "Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker"]
    },
    {
      "scene_number": 16,
      "caption": "The dragon lands on the castle roof, forcing a new escape route.",
      "visual_description": "A massive red dragon perches on the keep's battlements, smoke curling from its nostrils, the party scrambles toward a side exit.",
      "characters": ["The Dragon", "Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker", "The Captive"]
    },
    {
      "scene_number": 17,
      "caption": "The party races across the final escape bridge.",
      "visual_description": "A narrow stone bridge spanning a deep chasm, missing railings, cracked stones, the dragon swoops behind them, breathing fire.",
      "characters": ["Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "Zara the Bridge Walker", "The Captive", "The Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "Zara cuts the bridge, collapsing it behind them.",
      "visual_description": "Zara slices a rope holding the bridge, the stone structure crumbles into the chasm, the dragon roars in frustration on the far side.",
      "characters": ["Zara the Bridge Walker", "Lira the Map Reader", "Kael the Scout", "Mira the Magic Helper", "Finn the Comic Relief Official", "The Captive"]
    }
  ]
}

